INSERT INTO `site_content` (`id`, `content_key`, `page`, `section`, `section_label`, `field_type`, `default_value`, `value`, `sort_order`, `updated_at`) VALUES ('441', 'about.a-place-where-programming.02', 'about', 'a-place-where-programming', 'A Place Where Programming Is Taught Seriously.', 'textarea', 'Since 2015, Chedo Tech has been helping students go from zero knowledge of coding to building real projects. Our classrooms are offline — whiteboard teaching, live coding, and hands-on practice with the instructor beside you. No screen-sharing, real learning.', 'Since 2015, Chedo Tech has been helping students go from zero knowledge of coding to building real projects. Our classrooms are offline — whiteboard teaching, live coding, and hands-on practice with the instructor beside you. No screen-sharing, real learning.', '441', '2026-10-16 15:32:45');
