INSERT INTO `site_content` (`id`, `content_key`, `page`, `section`, `section_label`, `field_type`, `default_value`, `value`, `sort_order`, `updated_at`) VALUES ('6967', 'privacy.information-you-send-us.02', 'privacy', 'information-you-send-us', 'Information You Send Us', 'text', 'Course finder (contact page).', 'Course finder (contact page).', '3529', '2026-10-17 14:35:55');
INSERT INTO `site_content` (`id`, `content_key`, `page`, `section`, `section_label`, `field_type`, `default_value`, `value`, `sort_order`, `updated_at`) VALUES ('6968', 'privacy.information-you-send-us.03', 'privacy', 'information-you-send-us', 'Information You Send Us', 'textarea', 'When you use the \"Find My Best Courses\" form, your answers (such as age, education, preferred language, interests, goal and experience) are sent to our server only to calculate course suggestions, and are not saved. If you then choose \"Talk to a Mentor\", WhatsApp opens on your device with your details pre-filled, and nothing is sent until you press send in WhatsApp.', 'When you use the \"Find My Best Courses\" form, your answers (such as age, education, preferred language, interests, goal and experience) are sent to our server only to calculate course suggestions, and are not saved. If you then choose \"Talk to a Mentor\", WhatsApp opens on your device with your details pre-filled, and nothing is sent until you press send in WhatsApp.', '3530', '2026-10-17 14:35:55');
INSERT INTO `site_content` (`id`, `content_key`, `page`, `section`, `section_label`, `field_type`, `default_value`, `value`, `sort_order`, `updated_at`) VALUES ('6969', 'privacy.information-you-send-us.04', 'privacy', 'information-you-send-us', 'Information You Send Us', 'text', 'Chat assistant.', 'Chat assistant.', '3531', '2026-10-17 14:35:55');
INSERT INTO `site_content` (`id`, `content_key`, `page`, `section`, `section_label`, `field_type`, `default_value`, `value`, `sort_order`, `updated_at`) VALUES ('6970', 'privacy.information-you-send-us.05', 'privacy', 'information-you-send-us', 'Information You Send Us', 'textarea', 'When you ask the chat assistant (the owl button) a question, your question and the earlier messages in that chat are sent to our server and to NVIDIA\'s AI service to write the answer. We do not save chat messages, and the conversation is kept only in your browser until you close the tab. Please don\'t share passwords, payment details or other sensitive information in the chat.', 'When you ask the chat assistant (the owl button) a question, your question and the earlier messages in that chat are sent to our server and to NVIDIA\'s AI service to write the answer. We do not save chat messages, and the conversation is kept only in your browser until you close the tab. Please don\'t share passwords, payment details or other sensitive information in the chat.', '3532', '2026-10-17 14:35:55');
INSERT INTO `site_content` (`id`, `content_key`, `page`, `section`, `section_label`, `field_type`, `default_value`, `value`, `sort_order`, `updated_at`) VALUES ('6971', 'privacy.information-you-send-us.06', 'privacy', 'information-you-send-us', 'Information You Send Us', 'text', 'Enquiry forms.', 'Enquiry forms.', '3533', '2026-10-17 14:35:55');
INSERT INTO `site_content` (`id`, `content_key`, `page`, `section`, `section_label`, `field_type`, `default_value`, `value`, `sort_order`, `updated_at`) VALUES ('6972', 'privacy.information-you-send-us.07', 'privacy', 'information-you-send-us', 'Information You Send Us', 'textarea', 'If you submit an enquiry form on a course page, or the contact form while JavaScript is turned off in your browser, we save the details you enter (name, phone number, email, the course you are interested in and your message) in our enquiry records so our team can contact you.', 'If you submit an enquiry form on a course page, or the contact form while JavaScript is turned off in your browser, we save the details you enter (name, phone number, email, the course you are interested in and your message) in our enquiry records so our team can contact you.', '3534', '2026-10-17 14:35:55');
INSERT INTO `site_content` (`id`, `content_key`, `page`, `section`, `section_label`, `field_type`, `default_value`, `value`, `sort_order`, `updated_at`) VALUES ('6973', 'privacy.information-you-send-us.08', 'privacy', 'information-you-send-us', 'Information You Send Us', 'textarea', 'Information you send us by any of these routes, or by WhatsApp, phone, email or in person, is used only to respond to your enquiry and to help you with course guidance. We do not sell it or share it with advertisers. We keep enquiry records only for as long as we need them to follow up with you.', 'Information you send us by any of these routes, or by WhatsApp, phone, email or in person, is used only to respond to your enquiry and to help you with course guidance. We do not sell it or share it with advertisers. We keep enquiry records only for as long as we need them to follow up with you.', '3535', '2026-10-17 14:35:55');
INSERT INTO `site_content` (`id`, `content_key`, `page`, `section`, `section_label`, `field_type`, `default_value`, `value`, `sort_order`, `updated_at`) VALUES ('6974', 'privacy.information-we-collect-automatically.01', 'privacy', 'information-we-collect-automatically', 'Information We Collect Automatically', 'text', 'Information We Collect Automatically', 'Information We Collect Automatically', '3536', '2026-10-17 14:35:55');
INSERT INTO `site_content` (`id`, `content_key`, `page`, `section`, `section_label`, `field_type`, `default_value`, `value`, `sort_order`, `updated_at`) VALUES ('6975', 'privacy.information-we-collect-automatically.02', 'privacy', 'information-we-collect-automatically', 'Information We Collect Automatically', 'textarea', 'This website does not use analytics trackers, advertising scripts or tracking cookies. Our hosting provider may keep standard server logs (such as IP addresses, browser type and requested pages) as part of normal operation and security.', 'This website does not use analytics trackers, advertising scripts or tracking cookies. Our hosting provider may keep standard server logs (such as IP addresses, browser type and requested pages) as part of normal operation and security.', '3537', '2026-10-17 14:35:55');
