INSERT INTO `testimonials` (`id`, `student_name`, `course`, `testimonial`, `rating`, `review_date`, `source`, `source_url`, `status`, `sort_order`, `created_at`) VALUES ('1', 'Tanushri Wawge', '', 'The instructor\'s clear and practical explanations of MERN stack concepts made learning engaging and effective, greatly improving my full-stack skills.', '5', '4 weeks ago', 'google', 'https://maps.google.com/?q=Chedo+Tech+Kondhwa+Budruk+Pune', '1', '1', '2026-10-16 15:32:44');
INSERT INTO `testimonials` (`id`, `student_name`, `course`, `testimonial`, `rating`, `review_date`, `source`, `source_url`, `status`, `sort_order`, `created_at`) VALUES ('2', 'Gayatri Pawar', '', 'This hands-on, project-based coding class with great instructor support and small classes is perfect for beginners to gain real-world skills.', '5', '4 weeks ago', 'google', 'https://maps.google.com/?q=Chedo+Tech+Kondhwa+Budruk+Pune', '1', '2', '2026-10-16 15:32:44');
INSERT INTO `testimonials` (`id`, `student_name`, `course`, `testimonial`, `rating`, `review_date`, `source`, `source_url`, `status`, `sort_order`, `created_at`) VALUES ('3', 'Arya Nevase', '', 'Chedo Tech made learning C practical and engaging with clear teaching and real-world examples, building strong coding fundamentals.', '5', '4 weeks ago', 'google', 'https://maps.google.com/?q=Chedo+Tech+Kondhwa+Budruk+Pune', '1', '3', '2026-10-16 15:32:44');
INSERT INTO `testimonials` (`id`, `student_name`, `course`, `testimonial`, `rating`, `review_date`, `source`, `source_url`, `status`, `sort_order`, `created_at`) VALUES ('4', 'Omkar Hole', '', 'The teaching is excellent, focusing on practical examples and effective problem-solving, making complex topics easy to understand and apply.', '5', '4 weeks ago', 'google', 'https://maps.google.com/?q=Chedo+Tech+Kondhwa+Budruk+Pune', '1', '4', '2026-10-16 15:32:44');
INSERT INTO `testimonials` (`id`, `student_name`, `course`, `testimonial`, `rating`, `review_date`, `source`, `source_url`, `status`, `sort_order`, `created_at`) VALUES ('5', 'Ritvij Dixit', '', 'Great course! Sir was knowledgeable and provided clear explanations. Hands-on exercises were helpful. Highly recommended.', '5', '4 weeks ago', 'google', 'https://maps.google.com/?q=Chedo+Tech+Kondhwa+Budruk+Pune', '1', '5', '2026-10-16 15:32:44');
INSERT INTO `testimonials` (`id`, `student_name`, `course`, `testimonial`, `rating`, `review_date`, `source`, `source_url`, `status`, `sort_order`, `created_at`) VALUES ('6', 'Karishma Sandupatla', '', 'Chedo Tech is an excellent place to learn Python full stack with supportive instructors, clear teaching, and hands-on projects. Highly recommended!', '5', '4 weeks ago', 'google', 'https://maps.google.com/?q=Chedo+Tech+Kondhwa+Budruk+Pune', '1', '6', '2026-10-16 15:32:44');
